import * as React from 'react';
import { cn } from '@/lib/utils';

export type BreadcrumbItem = {
  /** Display label. */
  label: string;
  /** Destination href; omit for the current page (renders as plain text). */
  href?: string;
};

export type BreadcrumbProps = React.HTMLAttributes<HTMLElement> & {
  /** Ordered list of breadcrumb items; the last item is the current page. */
  items: BreadcrumbItem[];
  /** Separator character between items (default '/'). */
  separator?: React.ReactNode;
  /**
   * Receives every link click with the item and its index. When provided,
   * default navigation is prevented so you can route programmatically
   * (e.g. via a router, state machine, or analytics wrapper).
   */
  onItemClick?: (item: BreadcrumbItem, index: number) => void;
  /** Custom link element for routers (Next Link, react-router Link). */
  linkComponent?: React.ElementType;
};

/**
 * Navigation breadcrumb trail. The last item is rendered as the current
 * page with aria-current="page". Earlier items are links. Screen readers
 * announce the navigation landmark and current location.
 */
const Breadcrumb = React.forwardRef<HTMLElement, BreadcrumbProps>(
  ({ items, separator = '/', onItemClick, linkComponent, className, ...props }, ref) => {
    const LinkEl = linkComponent ?? 'a';
    return (
    <nav
      ref={ref}
      aria-label="Breadcrumb"
      className={cn('flex items-center space-x-1.5 text-sm text-muted-foreground', className)}
      {...props}
    >
      <ol className="flex flex-wrap items-center space-x-1.5">
        {items.map((item, index) => {
          const isLast = index === items.length - 1;
          return (
            <li key={`${item.label}-${index}`} className="flex items-center space-x-1.5">
              {index > 0 && (
                <span aria-hidden="true" className="text-muted-foreground/50">
                  {separator}
                </span>
              )}
              {item.href && !isLast ? (
                <LinkEl
                  href={item.href}
                  className="transition-colors hover:text-foreground"
                  onClick={
                    onItemClick
                      ? (event: React.MouseEvent<HTMLAnchorElement>) => {
                          event.preventDefault();
                          onItemClick(item, index);
                        }
                      : undefined
                  }
                >
                  {item.label}
                </LinkEl>
              ) : (
                <span
                  aria-current={isLast ? 'page' : undefined}
                  className={isLast ? 'font-medium text-foreground' : undefined}
                >
                  {item.label}
                </span>
              )}
            </li>
          );
        })}
      </ol>
    </nav>
    );
  }
);
Breadcrumb.displayName = 'Breadcrumb';

export { Breadcrumb };

{
  "id": "breadcrumb",
  "name": "Breadcrumb",
  "tier": "molecule",
  "description": "Navigation breadcrumb trail with links and current-page indicator",
  "designIntent": "Breadcrumb shows the user's location in a hierarchy and lets them navigate back to parent levels. The last item is the current page, marked with aria-current=page.",
  "props": [
    {
      "name": "items",
      "type": "BreadcrumbItem[]",
      "required": true,
      "description": "Ordered breadcrumb items; the last is the current page"
    },
    {
      "name": "separator",
      "type": "ReactNode",
      "defaultValue": "'/'",
      "required": false,
      "description": "Separator character between items"
    },
    {
      "name": "className",
      "type": "string",
      "required": false,
      "description": "Additional CSS classes to apply"
    },
    {
      "name": "onItemClick",
      "type": "(item: BreadcrumbItem, index: number) => void",
      "required": false,
      "description": "Receives every link click with default navigation prevented — route programmatically."
    },
    {
      "name": "linkComponent",
      "type": "React.ElementType",
      "required": false,
      "description": "Custom link element for routers (preserves prefetch/modified clicks)."
    }
  ],
  "examples": [
    {
      "title": "Three-level breadcrumb",
      "code": "<Breadcrumb items={[\n  { label: 'Home', href: '/' },\n  { label: 'Docs', href: '/docs' },\n  { label: 'Components' },\n]} />",
      "description": "Hierarchical navigation with current page"
    },
    {
      "title": "Custom separator",
      "code": "<Breadcrumb\n  items={[{ label: 'Home', href: '/' }, { label: 'Page' }]}\n  separator=\"›\"\n/>",
      "description": "Breadcrumb with a chevron separator"
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use Breadcrumb for flat navigation",
      "explanation": "Breadcrumb is for hierarchical structures. Use a nav menu or tabs for flat peer pages."
    },
    {
      "title": "Don't make the current page a link",
      "explanation": "The last item should be plain text with aria-current=page, not a link to itself."
    }
  ],
  "accessibility": [
    {
      "feature": "Navigation landmark",
      "implementation": "nav[aria-label=Breadcrumb] so screen readers announce the landmark",
      "userRequirements": "Don't place multiple breadcrumbs on one page"
    },
    {
      "feature": "Current page",
      "implementation": "Last item has aria-current=page",
      "userRequirements": "Only one item should have aria-current"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Labels",
      "guidelines": [
        "Use short nouns",
        "Match the page title of each level",
        "Avoid abbreviations"
      ],
      "goodExamples": [
        "Home",
        "Documentation",
        "Components"
      ],
      "badExamples": [
        "H",
        "Docs / Components / Button page",
        "Click here"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Link",
      "relationship": "Non-last items should be links",
      "example": "<Breadcrumb items={[{ label: 'Home', href: '/' }, { label: 'Current' }]} />"
    }
  ],
  "relatedComponents": [
    "Menu",
    "Tabs"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "breadcrumb",
  "exportName": "Breadcrumb"
}
